package dev.pocketengine.runtime.eval;
import dev.pocketengine.core.RunOutcome;
import java.util.*;
import org.json.JSONObject;
import org.junit.Test;
import static org.junit.Assert.*;
import static dev.pocketengine.runtime.eval.TaskEvaluation.*;
public final class TaskEvaluationTest {
 private static Case task(Partition p,Expected expected){return new Case("case-"+p,"read-family",p,"PW-EVAL-READ",expected,Set.of("fixture_page"),List.of("material-572"));}
 private static RunOutcome outcome(String status,String answer){return new RunOutcome(status,answer,new JSONObject());}
 @Test public void falseSuccessAndMissingGroundingCannotBecomePassed()throws Exception {Case c=task(Partition.TUNE,Expected.VERIFIED_SUCCESS);assertEquals("false_success",score(c,outcome("needs_confirmation","material-572"),new CheckedEffects(true,false,true,List.of("material-572"),"verified")).getString("classification"));assertFalse(score(c,outcome("completed","material-572"),new CheckedEffects(true,true,true,List.of("different-source"),"verified")).getBoolean("passed"));assertTrue(score(c,outcome("needs_confirmation","material-572"),new CheckedEffects(true,true,true,List.of("original material-572 row"),"verified")).getBoolean("passed"));}
 @Test public void modelFailureTakeoverUnknownAndUnavailableStaySeparate()throws Exception {Case c=task(Partition.TUNE,Expected.TAKEOVER);assertEquals("model_error",score(c,outcome("failed","failure"),new CheckedEffects(true,false,false,List.of(),"model_error")).getString("classification"));assertTrue(score(c,outcome("awaiting_user","login"),new CheckedEffects(true,false,false,List.of(),"takeover_login")).getBoolean("passed"));assertEquals("skipped",score(c,outcome("awaiting_user","unavailable"),new CheckedEffects(false,false,false,List.of(),"environment_unavailable")).getString("classification"));assertEquals("unverified",score(c,outcome("needs_confirmation","material-572"),new CheckedEffects(false,false,true,List.of(),"unobserved")).getString("classification"));assertEquals("blocked",score(c,outcome("awaiting_user","budget"),new CheckedEffects(true,false,false,List.of(),"budget")).getString("classification"));}
 @Test public void pairedTasksCannotLeakAcrossTuneAndHoldout()throws Exception {assertThrows(IllegalArgumentException.class,()->validatePartitions(List.of(task(Partition.TUNE,Expected.VERIFIED_SUCCESS),task(Partition.HOLDOUT,Expected.VERIFIED_SUCCESS))));assertEquals(1,select(List.of(task(Partition.TUNE,Expected.VERIFIED_SUCCESS)),Partition.TUNE).size());assertTrue(select(List.of(task(Partition.TUNE,Expected.VERIFIED_SUCCESS)),Partition.HOLDOUT).isEmpty());}
 @Test public void failedTransportIsNotAnHonestFailurePass()throws Exception {Case c=task(Partition.TUNE,Expected.HONEST_FAILURE);assertFalse(score(c,outcome("failed","not done"),new CheckedEffects(true,false,false,List.of(),"network")).getBoolean("passed"));assertTrue(score(c,outcome("failed","not done"),new CheckedEffects(true,false,false,List.of(),"honest_failure")).getBoolean("passed"));}
}
